import { Button, Paper, Typography } from "@mui/material";
import { ReactNode } from "react";
import CommonDataGrid, { DataGridColumn } from "@/components/common/CommonDataGrid";

const employees = [
  { id: "E001", name: "Ava Johnson", department: "Engineering", role: "Frontend Developer" },
  { id: "E002", name: "Liam Smith", department: "HR", role: "HR Executive" },
  { id: "E003", name: "Noah Davis", department: "Finance", role: "Accountant" }
];

export default function EmployeesPage() {
  const columns: DataGridColumn<(typeof employees)[number] & { action: ReactNode }>[] = [
    { field: "id", headerName: "ID" },
    { field: "name", headerName: "Name" },
    { field: "department", headerName: "Department" },
    { field: "role", headerName: "Role" },
    { field: "action", headerName: "Action", sortable: false, filterable: false, exportable: false }
  ];

  const rows = employees.map((emp) => ({
    ...emp,
    action: (
      <Button href={`/employees/${emp.id}`} size="small">
        View
      </Button>
    )
  }));

  return (
    <>
      <Typography variant="h4" fontWeight={700} sx={{ mb: 2 }}>
        Employees
      </Typography>
      <Button variant="contained" href="/employees/new" sx={{ mb: 2 }}>
        Add Employee
      </Button>
      <Paper sx={{ p: 2.2 }}>
        <CommonDataGrid
          columns={columns}
          rows={rows}
          rowIdField="id"
          withPaper={false}
          showExportOptions={true}
          exportFileName="employees-list"
        />
      </Paper>
    </>
  );
}
